package gen

import (
	"fmt"
)

// ValidateAPIWalkerCompleteness verifies the per-entity walker generated by the
// `api/field-options` template will have a `case` clause for every
// **API-readable** column AND every relationship into an API-exposed entity —
// and that access-restricted (non-readable) columns and relationships into a
// hidden entity have **no** case (PRD §26.5.2, amended by §32.3 and §26.10).
//
// The walker template iterates over APITableContext.Fields, gating each case
// on the field's Readable flag. A readable column missing its case would
// silently produce a nil entry on the resulting FieldOptions tree at runtime;
// a non-readable column with a live case would be dead code masking the
// access projection (the schema type has no such field to select). This lint
// is the fail-fast guard against both — codegen errors out with a descriptive
// message naming the offending column/relationship and entity.
//
// The relationship half checks the same two directions against
// exposedTargets, the struct names on the API (apiExposedTargets). A
// relationship into a hidden entity is that half's access-restricted column:
// the object type has no field for it, because the field would name a type
// the schema never declares.
//
// The third direction is the row-identity block the walker ends with; see
// validateAPIRowIdentityProjection.
//
// It takes an APIEntity — the column set plus the relationship set, plus the
// kind/name pair the message is phrased in — rather than a TableContext, so a
// view is linted by this exact code path with no special case. A view
// carries no relationships, so the second loop simply has nothing to check for
// it, which is the correct outcome and not an exemption; a view passes nil
// exposedTargets for that reason.
//
// Returns the first offending entry found; the caller may surface it as-is.
func ValidateAPIWalkerCompleteness(src APIEntity, apiTable APITableContext, exposedTargets map[string]bool) error {
	// SQLName → the field's walker-case liveness (the Readable flag the
	// field-options template gates each case on).
	apiCols := make(map[string]bool, len(apiTable.Fields))
	for _, f := range apiTable.Fields {
		apiCols[f.SQLName] = f.Readable
	}
	for _, c := range src.Columns {
		hasCase, present := apiCols[c.Name]
		readable := columnAccessCapabilities(c).APIReadable
		if readable && (!present || !hasCase) {
			return fmt.Errorf(
				"api: walker for %s %q has no case for column %q "+
					"(every API-readable column must appear in the GraphQL field-selection walker per PRD §26.5.2)",
				src.Kind, src.Name, c.Name,
			)
		}
		if !readable && present && hasCase {
			return fmt.Errorf(
				"api: walker for %s %q has a case for access-restricted column %q "+
					"(non-API-readable columns must not appear in the GraphQL field-selection walker per PRD §26.5.2 / §32.3)",
				src.Kind, src.Name, c.Name,
			)
		}
	}

	apiRels := make(map[string]bool, len(apiTable.Relationships))
	for _, r := range apiTable.Relationships {
		apiRels[r.SQLName] = true
	}
	for _, r := range src.Relationships {
		exposed := exposedTargets[r.TargetStructName]
		if exposed && !apiRels[r.Name] {
			return fmt.Errorf(
				"api: walker for %s %q has no case for relationship %q "+
					"(every relationship into an API-exposed entity must appear in the GraphQL field-selection walker per PRD §26.5.2)",
				src.Kind, src.Name, r.Name,
			)
		}
		if !exposed && apiRels[r.Name] {
			return fmt.Errorf(
				"api: walker for %s %q has a case for relationship %q into %s, which is not on the API "+
					"(a relationship into a hidden entity must not appear in the GraphQL field-selection walker per PRD §26.5.2 / §26.10)",
				src.Kind, src.Name, r.Name, r.TargetStructName,
			)
		}
	}
	return validateAPIRowIdentityProjection(src, apiTable)
}

// validateAPIRowIdentityProjection is the walker lint's third direction, over
// the row-identity block the template emits *after* the switch: the fields set
// when a selection asks for the row but names no column.
//
// Those assignments sit outside the switch, so the two directions above do not
// reach them — a field named here is projected into the SELECT whether or not
// the walker emits a case for it. §32.3's "access-restricted columns must not
// appear in the walker" governs this block exactly as it governs the switch,
// so the same column set must satisfy both: every projected field must name a
// column of the entity, and that column must be API-readable.
//
// That currently holds by coincidence rather than by construction —
// rowIdentityFields resolves the set from PKColumns, a view's CursorKeys, then
// Columns[0], none of which consults §32.2. Two facts outside it keep the
// result readable: §32.4 hard-errors on a restricted PK (config/validate.go),
// and a view has no column_map so every view column is public
// (context_view.go). Both are properties of surfaces that could grow, and
// neither is stated where rowIdentityFields lives — this lint is what fails
// loudly if either stops holding, rather than silently over-projecting.
//
// The emptiness check is the opposite failure: an entity that can project
// something but names nothing walks to an all-false FieldOptions, which PRD
// §9.6 reads as "the caller wants no rows", silently dropping the rows the
// request asked for.
//
// Both checks are scoped to an entity that has an API read surface at all. An
// entity whose every column is access-restricted exposes no selectable column
// and emits a walker with no case clauses, so what its row-identity block names
// is moot beside the larger defect — that such an entity reaches the API
// surface at all. §32.4 requires a readable PK, and the schema template would
// emit an empty `type <T> {}` gqlgen rejects; diagnosing that belongs to the
// rule that owns it, so it is exempted here rather than reported under a
// row-identity message that names the wrong cause.
//
// The exemption rests on the state being unreachable through a validated
// config, NOT on the walker being unreachable: a parent's relationship case
// descends into the target's walker regardless of the target's readability
// (relationship cases are not gated on it), so the walker is still callable.
// Reaching the state at all takes bypassing config validation the way the
// §26.5.3 target-exposure tests deliberately do.
func validateAPIRowIdentityProjection(src APIEntity, apiTable APITableContext) error {
	// GoFieldName → the field, keyed the way the row-identity block names its
	// entries (`fo.<GoFieldName> = true`) rather than by SQL name. Both spell
	// ColumnContext.FieldName, so the two keyings name the same column.
	byGoField := make(map[string]APIFieldContext, len(apiTable.Fields))
	readable := 0
	for _, f := range apiTable.Fields {
		byGoField[f.GoFieldName] = f
		if f.Readable {
			readable++
		}
	}
	if readable == 0 {
		return nil
	}

	if len(apiTable.RowIdentityFields) == 0 {
		return fmt.Errorf(
			"api: walker for %s %q has API-readable columns but projects no row identity "+
				"(a selection that names no column must still project one, or PRD §9.6's all-false "+
				"short-circuit swallows a row the request asked for)",
			src.Kind, src.Name,
		)
	}

	for _, goField := range apiTable.RowIdentityFields {
		f, ok := byGoField[goField]
		if !ok {
			return fmt.Errorf(
				"api: walker for %s %q projects row-identity field %q, which names no column of the entity "+
					"(the row-identity block may only project columns the walker also emits a case for per PRD §26.5.2)",
				src.Kind, src.Name, goField,
			)
		}
		if !f.Readable {
			return fmt.Errorf(
				"api: walker for %s %q projects access-restricted column %q as its row identity "+
					"(the walker emits no case for a non-API-readable column, so it must not be projected "+
					"outside the switch either per PRD §26.5.2 / §32.3)",
				src.Kind, src.Name, f.SQLName,
			)
		}
	}
	return nil
}
